import { normalizeDataList, normalizeLayoutResponse, unwrapData } from './runtimePageDataHelpers.js';
import { configureColorLibraryClient, refreshColorLibrary } from '../../shared/colors/colorLibrary.js';
import { configureFontPackagesClient, refreshFontPackages } from '../../shared/fonts/fontPackages.js';
export { adminLaneAuthPayload, laneAuthPayload, normalizeDataList, normalizeLayoutResponse, resolveRuntimeWidgetLane, unwrapData } from './runtimePageDataHelpers.js';
export async function initializeRuntimeDesignDefaults(emit, lane) {
    const normalizedLane = lane === 'admin' ? 'admin' : 'public';
    const token = normalizedLane === 'admin' ? window.ADMIN_TOKEN : window.PUBLIC_TOKEN;
    configureColorLibraryClient({ emit, token, lane: normalizedLane });
    configureFontPackagesClient({ emit, token, lane: normalizedLane });
    await Promise.all([refreshColorLibrary().catch(error => {
            console.warn('COLOR_LIBRARY_RUNTIME_LOAD_FAILED: Linked colors will use serialized fallbacks.', error);
        }), refreshFontPackages().catch(error => {
            console.warn('FONT_PACKAGES_RUNTIME_LOAD_FAILED: Content will use its serialized or browser typography.', error);
        })]);
}
function cmsPublicRuntimePayload(resource, action, params = {}) {
    return {
        moduleName: 'runtimeManager',
        moduleType: 'core',
        resource,
        action,
        params
    };
}
function cmsAdminPayload(resource, action, params = {}) {
    return {
        jwt: window.ADMIN_TOKEN,
        moduleName: 'runtimeManager',
        moduleType: 'core',
        resource,
        action,
        params
    };
}
export async function fetchRuntimePageBySlug(emit, slug, lane) {
    // Account editors are details of the registered Users & access page, not
    // database page records per user/provider. Keep their existing deep links.
    const settingsDetail = lane === 'admin' && (/^settings\/users\/edit\/\d+$/.test(slug) || slug === 'settings/login/edit');
    const pageSlug = settingsDetail ? 'settings/users-access' : slug;
    const eventName = lane === 'admin' ? 'cmsAdminApiRequest' : 'cmsPublicRuntimeRequest';
    const payload = lane === 'admin'
        ? cmsAdminPayload('pages', 'getBySlug', { slug: pageSlug, lane })
        : cmsPublicRuntimePayload('pages', 'getBySlug', { slug, lane });
    const page = unwrapData(await emit(eventName, payload));
    return settingsDetail && page ? { ...page, slug, title: slug.startsWith('settings/users/') ? 'Edit user' : 'Configure sign-in' } : page;
}
export async function fetchRuntimePublicSettings(emit, lane, keys) {
    const eventName = lane === 'admin' ? 'cmsAdminApiRequest' : 'cmsPublicRuntimeRequest';
    const payload = lane === 'admin'
        ? cmsAdminPayload('settings', 'public', { keys })
        : cmsPublicRuntimePayload('settings', 'public', { keys });
    const value = unwrapData(await emit(eventName, payload));
    return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}
